# Features: m_0_0_0_0, m_0_0_1_0, m_0_2_0_0, m_1_0_0_1
def equation(x0, x1, x2, x3, params):
    params = np.asarray(params, dtype=float)
    if params.shape != (4,) or not np.all(np.isfinite(params)):
        raise ValueError('invalid coefficient vector')
