    x1 = np.asarray(x1, dtype=float).ravel()
    x2 = np.asarray(x2, dtype=float).ravel()
    x3 = np.asarray(x3, dtype=float).ravel()
    if x0.size == 0 or x1.shape != x0.shape or x2.shape != x0.shape or x3.shape != x0.shape or not np.all(np.isfinite(x0)) or not np.all(np.isfinite(x1)) or not np.all(np.isfinite(x2)) or not np.all(np.isfinite(x3)):
        raise ValueError('invalid input columns')
    with np.errstate(over='ignore', invalid='ignore'):
        output = np.zeros_like(x0, dtype=float)
        output = output + params[0]
        output = output + params[1] * x2
        output = output + params[2] * (x1 ** 2)
        output = output + params[3] * x0 * x3
    return np.nan_to_num(output, nan=0.0, posinf=1e6, neginf=-1e6)
